[{"order":1,"type":"heading","text":"Testing, Benchmarking, and Fuzzing in Go"},{"order":2,"type":"paragraph","text":"Go provides a robust, built-in toolchain for testing, performance benchmarking, and fuzzing. Utilizing the testing package, developers can ensure reliability, optimize performance bottlenecks, and discover edge cases without relying on heavy external frameworks."},{"order":3,"type":"subheading","text":"1. Standard Unit Testing"},{"order":4,"type":"paragraph","text":"Unit tests in Go reside in files ending with _test.go and use functions starting with Test followed by a capitalized word. Below is an example of a simple math utility function and its corresponding test."},{"order":5,"type":"code","text":"package mathutil

func Add(a, b int) int {
    return a + b
}"},{"order":6,"type":"code","text":"package mathutil

import "testing"

func TestAdd(t *testing.T) {
    result := Add(2, 3)
    expected := 5
    if result != expected {
        t.Errorf("Add(2, 3) = %d; expected %d", result, expected)
    }
}"},{"order":7,"type":"subheading","text":"2. Table-Driven Tests"},{"order":8,"type":"paragraph","text":"Go idiomatically uses table-driven testing to run multiple test cases through the same logic efficiently. This reduces code duplication and simplifies adding new scenarios."},{"order":9,"type":"code","text":"func TestAddTable(t *testing.T) {
    tests := []struct {
        name     string
        a, b     int
        expected int
    }{
        {"positive numbers", 2, 3, 5},
        {"negative numbers", -1, -1, -2},
        {"zero values", 0, 0, 0},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            if got := Add(tt.a, tt.b); got != tt.expected {
                t.Errorf("Add(%d, %d) = %d; want %d", tt.a, tt.b, got, tt.expected)
            }
        })
    }
}"},{"order":10,"type":"subheading","text":"3. Performance Benchmarking"},{"order":11,"type":"paragraph","text":"Benchmarks measure the performance of Go code. Benchmark functions begin with Benchmark instead of Test and accept a pointer to testing.B. The testing runtime automatically adjusts the loop iteration count (b.N) to get reliable measurements."},{"order":12,"type":"code","text":"package mathutil

import "testing"

func BenchmarkAdd(b *testing.B) {
    for i := 0; i < b.N; i++ {
        Add(10, 20)
    }
}"},{"order":13,"type":"paragraph","text":"To execute the benchmarks, run the following command in your terminal: go test -bench=. -benchmem"},{"order":14,"type":"subheading","text":"4. Native Fuzzing"},{"order":15,"type":"paragraph","text":"Introduced in Go 1.18, native fuzzing passes randomized data to your functions to find security vulnerabilities, panics, and unexpected errors. Fuzz tests begin with Fuzz and accept testing.F."},{"order":16,"type":"code","text":"package stringutil

import (
    "unicode/utf8"
    "testing"
)

func FuzzReverse(f *testing.F) {
    f.Add("Hello")
    f.Add("世界")
    f.Fuzz(func(t *testing.T, orig string) {
        rev := Reverse(orig)
        doubleRev := Reverse(rev)
        if orig != doubleRev {
            t.Errorf("Before: %q, after: %q", orig, doubleRev)
        }
        if utf8.ValidString(orig) && !utf8.ValidString(rev) {
            t.Errorf("Reverse produced invalid UTF-8 string %q", rev)
        }
    })
}"},{"order":17,"type":"subheading","text":"Best Practices"},{"order":18,"type":"bullet_point","text":"Always use table-driven tests when testing functions with multiple input combinations."},{"order":19,"type":"bullet_point","text":"Reset timers using b.ResetTimer() inside benchmarks if your setup logic is expensive."},{"order":20,"type":"bullet_point","text":"Run fuzzing continuously in CI pipelines or longer local sessions to expose edge cases like integer overflows and encoding bugs."}]
